def _opinfo(raw, msl):
    if type(raw) is dict:
        raw = raw.get("")
    if raw is None:
        return _N, None
    if type(raw) is int:
        return raw + msl, ((-raw, '') if raw else None)
    c, a = raw
    return max(c + 1, c + msl - len(a)), (((-c if c else None), a) if (c or a) else None)


def _link(raw, msl, dag, memo):
    out = {}
    for k, v in raw.items():
        if not k:
            continue
        if type(v) in (list, tuple) and len(v) == 1:
            i = v[0]
            v = dag[i]
            child = memo.get(i)
            if child is None:
                child = memo[i] = _link(v, msl, dag, memo) if type(v) is dict else _E
        else:
            child = _link(v, msl, dag, memo) if type(v) is dict else _E
        nd, op = _opinfo(v, msl)
        ent = (child, nd, op)
        for ch in reversed(k[1:]):
            ent = ({ch: ent}, _N, None)
        out[k[0]] = ent
    return out


def _pfxinfo(raw, amin):
    if type(raw) is dict:
        raw = raw.get("")
    if type(raw) is not int:
        return _N, 0
    return (0 if raw == 0 else raw + amin), raw


def _plink(raw, amin):
    out = {}
    for k, v in raw.items():
        if not k:
            continue
        child = _plink(v, amin) if type(v) is dict else _E
        nd, op = _pfxinfo(v, amin)
        out[k] = (child, nd, op)
    return out


